/**
 * Automatically repairs common JSON syntax defects generated by LLMs:
 * - Trailing commas in objects/arrays
 * - Single-quoted strings and keys
 * - Unquoted object keys
 * - Unclosed braces/brackets
 */
export function repairJson(jsonText: string): { repairedText: string; repairApplied: boolean } {
  if (!jsonText || typeof jsonText !== 'string') {
    return { repairedText: jsonText, repairApplied: false };
  }

  let text = jsonText.trim();
  let repairApplied = false;

  // 1. Remove trailing commas before closing braces or brackets: ,} -> } or ,] -> ]
  const trailingCommaRegex = /,\s*([\}\]])/g;
  if (trailingCommaRegex.test(text)) {
    text = text.replace(trailingCommaRegex, '$1');
    repairApplied = true;
  }

  // 2. Fix unquoted keys e.g. { key: "val" } -> { "key": "val" }
  const unquotedKeyRegex = /([{,]\s*)([a-zA-Z_][a-zA-Z0-9_]*)\s*:/g;
  if (unquotedKeyRegex.test(text)) {
    text = text.replace(unquotedKeyRegex, '$1"$2":');
    repairApplied = true;
  }

  // 3. Fix single-quoted property keys or string values: 'key': 'val' -> "key": "val"
  const singleQuoteRegex = /'([^'\\]*(?:\\.[^'\\]*)*)'/g;
  if (singleQuoteRegex.test(text)) {
    text = text.replace(singleQuoteRegex, '"$1"');
    repairApplied = true;
  }

  // 4. Check for unclosed braces/brackets and append missing closures
  let openBraces = 0;
  let openBrackets = 0;
  let inString = false;
  let escape = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (escape) {
      escape = false;
      continue;
    }
    if (char === '\\') {
      escape = true;
      continue;
    }
    if (char === '"') {
      inString = !inString;
      continue;
    }
    if (!inString) {
      if (char === '{') openBraces++;
      else if (char === '}') openBraces = Math.max(0, openBraces - 1);
      else if (char === '[') openBrackets++;
      else if (char === ']') openBrackets = Math.max(0, openBrackets - 1);
    }
  }

  if (openBraces > 0 || openBrackets > 0) {
    repairApplied = true;
    while (openBrackets > 0) {
      text += ']';
      openBrackets--;
    }
    while (openBraces > 0) {
      text += '}';
      openBraces--;
    }
  }

  return {
    repairedText: text,
    repairApplied,
  };
}
